    color: '#475569',
    fontSize: 13,
  },
  stepCount: {
    color: '#64748b',
    fontSize: 12,
  },
  sectionList: {
    flex: 1,
  },
  sectionSeparator: {
    height: 8,
    backgroundColor: '#0a0f1e',
  },
  floorSection: {
    paddingHorizontal: 16,
    paddingVertical: 8,
  },
  floorHeader: {
    color: '#475569',
    fontSize: 11,
    fontWeight: '600',
    letterSpacing: 1,
    textTransform: 'uppercase',
    marginBottom: 8,
  },
  stepRow: {
    flexDirection: 'row',
    alignItems: 'flex-start',
    gap: 10,
    paddingVertical: 8,
    paddingHorizontal: 4,
  },
  stepRowAccessible: {
    backgroundColor: '#1c1408',
    borderRadius: 8,
    paddingHorizontal: 8,
  },
  stepIconContainer: {
    width: 32,
    height: 32,
    borderRadius: 8,
